				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$${\mathrm{RF}}{\kern 1pt} {\mathrm{index}}_{{\mathrm{mutant}}} = \frac{{\left( {{\mathrm{Count}}_{{\mathrm{mutant}},{\mathrm{post}} -{\mathrm{selection}}} + 1} \right){\mathrm{/}}\left( {{\mathrm{Count}}_{{\mathrm{mutant}},{\mathrm{input}}} + 1} \right)}}{{\left( {{\mathrm{Count}}_{{\mathrm{WT}},{\mathrm{post}} - {\mathrm{selection}}} + 1} \right){\mathrm{/}}\left( {{\mathrm{Count}}_{{\mathrm{WT}},{\mathrm{input}}} + 1} \right)}}$$\end{document}RFindexmutant=Countmutant,post-selection+1∕Countmutant,input+1CountWT,post-selection+1∕CountWT,input+1
